96		body := `{"events":[
97			{"id":"e1","service":"gateway","severity":" CRITICAL ","message":" spike ","at":"2026-10-01T10:00:00.123456789+08:00"},
98			{"id":"e2","service":"api","severity":"info","message":"ok","at":"2026-10-01T09:00:00Z"}
99		]}`
