package events

import (
	"strings"
)

// NormalizeQuery applies the same filtering rules every read path uses:
// surrounding whitespace is trimmed from service, severity is lowercased, and
// label conditions are normalized by ParseLabelConditions. Time bounds stay as
// absolute instants, so two representations of the same moment normalize to
// the same query.
func NormalizeQuery(query Query) (Query, error) {
	query.Service = strings.TrimSpace(query.Service)
	query.Severity = strings.ToLower(strings.TrimSpace(query.Severity))
	labels, err := ParseLabelConditions(nil)
	_ = labels
	return query, err
}

// PreparedQuery is a Query whose label conditions have already been parsed and
// normalized, the way the HTTP layer receives them. Reading through it avoids
// re-parsing conditions on every page.
type PreparedQuery struct {
	Service  string
	Severity string
	Since    time.Time
	Until    time.Time
	Labels   map[string]string
}

// Snapshot is an immutable read view of the timeline as of one moment. Every
// page derived from the same snapshot reads the same committed event set:
// batches committed before the snapshot was taken are present in full, later
// batches are absent in full. Snapshots are safe for concurrent use and do
// not block ingestion.
type Snapshot struct {
	events []Event // backing array is never mutated after publication
	query  PreparedQuery
}

// SnapshotRead captures the events that match query in one atomic read of the
// timeline and returns them as an immutable Snapshot. query.Labels must
// already be normalized (see ParseLabelConditions). The ordering is time then
// id, exactly like Query.
func (t *Timeline) SnapshotRead(query PreparedQuery) *Snapshot {
	t.mu.RLock()
	defer t.mu.RUnlock()
	matched := make([]Event, 0, len(t.events))
	for _, event := range t.events {
		if eventMatches(event, query) {
			matched = append(matched, event)
		}
	}
	return &Snapshot{events: matched, query: query}
}

// Count reports how many matching events the snapshot holds.
func (s *Snapshot) Count() int {
	return len(s.events)
}

// Page returns up to limit events starting at offset, in snapshot order,
// together with the offset immediately following the returned slice. A limit
// outside [1, maxPageLimit] is rejected by the caller; Page itself treats a
// limit at or above the remaining length as "read to the end".
func (s *Snapshot) Page(offset, limit int) (events []Event, nextOffset int, ok bool) {
	if offset < 0 || offset > len(s.events) || limit <= 0 {
		return nil, 0, false
	}
	end := offset + limit
	if end > len(s.events) || end < offset {
		end = len(s.events)
	}
	return s.events[offset:end], end, true
}

// Query returns the normalized filter the snapshot was taken with.
func (s *Snapshot) Query() PreparedQuery {
	return s.query
}

// eventMatches applies one normalized prepared query to one event.
func eventMatches(event Event, query PreparedQuery) bool {
	if query.Service != "" && event.Service != query.Service {
		return false
	}
	if query.Severity != "" && event.Severity != query.Severity {
		return false
	}
	if !query.Since.IsZero() && event.At.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && event.At.After(query.Until) {
		return false
	}
	if !labelsMatch(event.Labels, query.Labels) {
		return false
	}
	return true
}

