// after a restart. Paginated reads use it as an immutable snapshot boundary.
type Timeline struct {
	mu       sync.RWMutex
	byID     map[string]Event
	events   []Event
	nextSeq  int64
	seqByID  map[string]int64
}

// NewTimeline returns an empty timeline.
func NewTimeline() *Timeline {
	return &Timeline{byID: make(map[string]Event), seqByID: make(map[string]int64)}
}

// IngestResult counts how a batch was applied: Created events are new,
