			}
		}()
	}
	wg.Wait()

	// A fresh first page now includes the new commits.
	status, restarted := getPage(t, server, "?severity=critical&limit=10")
	if status != http.StatusOK || pageIDs(restarted) != "early,e0,sametime,e2" {
		t.Fatalf("new first page must see the current set: %d %+v", status, restarted)
	}
}

// eventsQueryCritical is a tiny indirection so the test above does not need to
// import the events package just for one query.
func eventsQueryCritical() events.QueryShim {
	return events.QueryShim{Severity: "critical"}
