// flipLastChar changes the final base64url character to a different valid
// one, so the token decodes but the signature no longer matches.
func flipLastChar(token string) string {
	b := []byte(token)
	if b[len(b)-1] == 'A' {
		b[len(b)-1] = 'B'
	} else {
		b[len(b)-1] = 'A'
	}
	return string(b)
}

