56	// the same filters GET /events accepts, and returns its first slice.
57	func (h *Handler) firstPage(w http.ResponseWriter, values url.Values, limit int) {
58		query, err := parseEventFilter(values)
59		if err != nil {
60			writeError(w, http.StatusBadRequest, err.Error())
61			return
62		}
63	
64		snapshot := h.timeline.SnapshotRead(events.PrepareQuery(query))
65		page, nextOffset, _ := snapshot.Page(0, limit)
66		h.writePage(w, snapshot.Query(), snapshot.IDs(), page, nextOffset)
67	}
68	
69	// nextPage resumes a frozen set from its cursor. Any filter parameter carried
70	// alongside the cursor must spell out the complete normalized filter set from
71	// the first page; a mismatch (including one changed condition) is a 400.
72	func (h *Handler) nextPage(w http.ResponseWriter, values url.Values, token string, limit int) {
73		cursor, err := decodeCursor(h.log, token)
74		if err != nil {
75			writeError(w, http.StatusBadRequest, "invalid or expired pagination cursor")
76			return
77		}
78	
79		if hasFilterParams(values) {
80			query, ferr := parseEventFilter(values)
81			if ferr != nil {
82				writeError(w, http.StatusBadRequest, ferr.Error())
83				return
84			}
85			if !events.PrepareQuery(query).EqualTo(cursor.preparedQuery()) {
86				writeError(w, http.StatusBadRequest, "query filters do not match the cursor's original filters")
87				return
88			}
89		}
90	
91		page, nextOffset, err := h.timeline.ResumePage(cursor.IDs, cursor.Offset, limit)
92		if err != nil {
93			writeError(w, http.StatusBadRequest, "invalid or expired pagination cursor")
94			return
95		}
96		h.writePage(w, cursor.preparedQuery(), cursor.IDs, page, nextOffset)
97	}
