99	// writePage mints the next cursor (or null at the end) and emits the page.
100	func (h *Handler) writePage(w http.ResponseWriter, query events.PreparedQuery, ids []string, page []events.Event, nextOffset int) {
101		resp := pageResponse{Events: eventsToDTOs(page)}
102		if nextOffset < len(ids) {
103			token, err := encodeCursor(h.log, newCursorData(query, ids, nextOffset))
104			if err != nil {
105				writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
106				return
107			}
108			resp.NextCursor = &token
109		}
110		writeJSON(w, http.StatusOK, resp)
111	}
112	
113	// singleCursor accepts the cursor parameter only when it is absent or appears
114	// exactly once with a non-empty value; a missing cursor starts a first page.
115	func singleCursor(w http.ResponseWriter, values url.Values) (string, bool, bool) {
116		raws, present := values["cursor"]
117		if !present {
118			return "", false, true
119		}
120		if len(raws) != 1 || raws[0] == "" {
121			writeError(w, http.StatusBadRequest, "cursor must be a single non-empty value")
122			return "", false, false
123		}
124		return raws[0], true, true
125	}
126	
127	// parsePageLimit enforces the single decimal integer rule and the 1..1000
128	// range, defaulting to defaultPageLimit when the parameter is absent.
129	func parsePageLimit(w http.ResponseWriter, values url.Values) (int, bool) {
130		raws, present := values["limit"]
131		if !present {
132			return defaultPageLimit, true
133		}
134		if len(raws) != 1 || raws[0] == "" || !isDecimal(raws[0]) {
135			writeError(w, http.StatusBadRequest, "limit must be a single decimal integer from 1 to 1000")
136			return 0, false
137		}
138		value, err := strconv.Atoi(raws[0])
139		if err != nil || value < 1 || value > events.MaxPageLimit {
140			writeError(w, http.StatusBadRequest, "limit must be a single decimal integer from 1 to 1000")
141			return 0, false
142		}
143		return value, true
144	}
145	
146	// filterParamNames are the GET /events filter keys, all of which must match a
147	// cursor's frozen set when any one of them accompanies a continuation.
148	var filterParamNames = [...]string{"service", "severity", "since", "until", "label"}
149	
150	func hasFilterParams(values url.Values) bool {
151		for _, name := range filterParamNames {
152			if _, present := values[name]; present {
153				return true
154			}
155		}
156		return false
157	}
158	
159	// parseEventFilter parses and validates the GET /events filter parameters,
160	// sharing their exact rules: trimmed service, case-insensitive severity,
161	// inclusive RFC3339Nano time bounds, and repeatable name=value labels.
162	func parseEventFilter(values url.Values) (events.Query, error) {
163		labels, err := events.ParseLabelConditions(values["label"])
164		if err != nil {
165			return events.Query{}, err
166		}
167		query := events.Query{
168			Service:  values.Get("service"),
169			Severity: values.Get("severity"),
170			Labels:   labels,
171		}
172		if raw := values.Get("since"); raw != "" {
173			parsed, err := time.Parse(time.RFC3339Nano, raw)
174			if err != nil {
175				return events.Query{}, errors.New("since must be an RFC3339Nano timestamp")
176			}
177			query.Since = parsed
178		}
179		if raw := values.Get("until"); raw != "" {
180			parsed, err := time.Parse(time.RFC3339Nano, raw)
181			if err != nil {
182				return events.Query{}, errors.New("until must be an RFC3339Nano timestamp")
183			}
184			query.Until = parsed
185		}
186		if !query.Since.IsZero() && !query.Until.IsZero() && query.Since.After(query.Until) {
187			return events.Query{}, errors.New("since must not be after until")
188		}
